  ui_story_30960401_57_dialog_content = "Em... ¿Es un boleto de ida a \"La Tierra de la Libertad y Riqueza Infinitas\"?",
  ui_story_30960401_58_dialog_content = "<size=40> ¿Dónde queda? </size> <size=45> Me encantaría visitar.</size> <size=50> Si voy allí, ¿me haré rico... y libre?</size>",
  ui_story_30960401_59_dialog_content = "Lo siento... Olvidé que siempre tomas las palabras literalmente ...",
  ui_story_30960401_60_dialog_content = "Me refiero a un billete de aeronave a Lumopolis.",
  ui_story_30960401_61_dialog_content = "¿Un boleto de aeronave? ¿Y eso cuesta 20 millones?",
  ui_story_30960401_62_dialog_content = "Exacto. Es la aeronave de pasajeros que circula entre Umbraton y Lumopolis todos los días.",
  ui_story_30960401_63_dialog_content = "¿Estás diciendo que cada boleto cuesta más de 20 millones? ¿Quién te dijo eso?",
  ui_story_30960401_64_dialog_content = "Kleken.",
  ui_story_30960401_65_dialog_content = "(Sé que tuvo algo que ver con esto...)",
  ui_story_30960401_66_dialog_content = "Calculé que si sigo trabajando en Umbraton, me llevará ... <color=#FFB400>3000</color> años más o menos para ganar suficiente dinero.",
  ui_story_30960401_67_dialog_content = "Mm... ¿O fueron <color=#FFB400>30.000</color> años? No lo recuerdo. Ah, y el número 3 es tan feo... Cambiémoslo a un 8...",
  ui_story_30960401_68_dialog_content = "Sariel, me viene a la mente cierto dicho... Pero no estoy seguro de si debería decirlo o no.",
  ui_story_30960401_69_dialog_content = "Yo tampoco lo sé... porque aún no lo he escuchado.",
  ui_story_30960401_70_dialog_content = "¿No crees que el precio es totalmente irreal? ¿Cómo podría alguien pagar un boleto tan caro?",
  ui_story_30960401_71_dialog_content = "...",
  ui_story_30960401_72_dialog_content = "¡Oh!",
  ui_story_30960401_73_dialog_content = "¡Entonces así es como es!",
  ui_story_30960401_74_dialog_content = "(¿Podría ser que ... Al fin lo entiende?)",
  ui_story_30960401_75_dialog_content = "Los otros pasajeros deben haber trabajado <size=45>realmente, realmente duro, ¿verdad</size>?",
  ui_story_30960401_76_dialog_content = "No... Deben haber trabajado durante <size=45> mucho, mucho tiempo, ¿verdad </size>?",
  ui_story_30960401_77_dialog_content = "Lo siento, sigo olvidando que estás ... algo limitada cuando se trata de sentido común...",
  ui_story_30960401_78_dialog_content = "Parece que te estás burlando de mí. Estoy muy familiarizado con esa mirada.",
  ui_story_30960401_79_dialog_content = "L-lo siento... Pero eres tan diferente de la mayoría de las personas que he conocido, Sariel.",
  ui_story_30960401_80_dialog_content = "¿En serio? ¿A qué te refieres?",
  ui_story_30960401_81_dialog_content = "Espera un minuto. Muévete un poco a la izquierda primero.",
  ui_story_30960401_82_dialog_content = "¿¿??",
  ui_story_30960401_83_dialog_content = "Te acabas de mover desde el punto medio de la pared. Ahora está bien. Estás simétrico de nuevo.",
  ui_story_30960401_84_dialog_content = "¿Entonces? ¿Cuál es la diferencia entre los demás y yo?",
  ui_story_30960401_85_dialog_content = "...",
  ui_story_30960401_86_dialog_content = "Sariel, déjame ver si puedo adivinar algo primero. Dime si estoy en lo cierto.",
  ui_story_30960401_87_dialog_content = "Ir a Lumopolis tiene algo que ver con Gabriela, ¿no?",
  ui_story_30960401_88_dialog_content = "...",
  ui_story_30960401_89_dialog_content = "(¿Adiviné correctamente?)",
  ui_story_30960401_90_dialog_content = "¿Tu... usaste tus habilidades psíquicas?",
  ui_story_30960401_91_dialog_content = "No... Es tan obvio.",
  ui_story_30960401_92_dialog_content = "¿Puedes decirme por qué la estás buscando? ¿Tal vez puedo ayudar? Es decir, además de los 20 millones...",
  ui_story_30960401_93_dialog_content = "Se trata de mi abuelo.",
  ui_story_30960401_94_dialog_content = "¿Abuelo?",
  ui_story_30960401_95_dialog_content = "Sí. Le voy a preguntar a Gabriela como murió.",
  ui_story_30960401_96_dialog_content = "Oh... Eso es... Entiendo...",
  ui_story_30960401_97_dialog_content = "Hace doce años. No, ¿fue eso hace diez años? Quedemos con la media de hace once años.",
  ui_story_30960401_98_dialog_content = "Mi abuelo, <color=#FFB400> Amos </color>, murió en Lumopolis.",
  ui_story_30960401_99_dialog_content = "Aún era joven entonces, y la mayoría de mis rec. de él son confusos, pero recuerdo una cosa muy claramente.",
  ui_story_30960401_100_dialog_content = "Un día, mi abuelo se fue de repente para emprender un largo viaje. Me dijo que me quedara en casa y que volvería pronto.",
  ui_story_30960401_101_dialog_content = "Y escuché un nombre—Gabriela. Ella fue la razón por la que mi abuelo tuvo que salir de casa e ir a Lumopolis.",
  ui_story_30960401_102_dialog_content = "No sabía que sería la última vez que lo vería.",
  ui_story_30960401_103_dialog_content = "No lo sabía... \"Sé una buena chica, Sariel\", serían sus últimas pal. para mí.",
  ui_story_30960401_104_option_content = "Lo siento por recordarte...",
  ui_story_30960401_105_dialog_content = "Gracias por tu preocupación, PlayerName ... Pero no tienes que disculparte.",
  ui_story_30960401_106_dialog_content = "Ese día siempre está en mi mente. Nunca lo olvidaré.",
  ui_story_30960401_107_dialog_content = "Ese día también dejó una pregunta latente en mi mente—¿quién es Gabriela?",
  ui_story_30960401_108_option_content = "Entiendo tu dolor.",
  ui_story_30960401_109_dialog_content = "Bueno, en cierto modo, tú y yo estamos buscando algo bastante similar.",
  ui_story_30960401_110_dialog_content = "La clave de mis rec. es Gabriela, una chica que nunca conocí.",
  ui_story_30960401_111_dialog_content = "El ángel de Lumopolis, Miembro de los Guardianes, la Chica en la Jaula de Pájaros...",
  ui_story_30960401_112_dialog_content = "Las historias y rumores, no han respondido ninguna de mis preguntas, así que debo ir y averiguarlo por mí misma.",
  ui_story_30960401_113_dialog_content = "Tengo que conocerla en persona y preguntarle qué pasó hace tantos años. Necesito saber qué le pasó a mi abuelo, Amos.",
  ui_story_30960401_114_dialog_content = "Y necesito saber... quién es ella en realidad.",
  ui_story_30960401_115_dialog_content = "Bueno, hasta donde yo sé, el pasado de Gabriela realmente no parece tan complicado... Pero, claro, no se toda la historia.",
  ui_story_30960401_116_dialog_content = "¿En serio? Pero ella debe saber algo, ¿no?",
  ui_story_30960401_117_dialog_content = "En Lumopolis, en esa isla flotante... Quizás allí encuentre las respuestas que he estado buscando.",
  ui_story_30960401_118_dialog_content = "...",
  ui_story_30960401_119_dialog_content = "Ah, sé que mi abuelo murió en el Hospital de Lumopolis.",
  ui_story_30960401_120_dialog_content = "Una herida grave lo puso en coma, y nunca despertó.",
  ui_story_30960401_121_dialog_content = "¿Tuvo algún tipo de accidente? ¿Estaba Gabriela involucrada?",
  ui_story_30960401_122_dialog_content = "Ni el Señor Sombrío sabe más que eso, así que tengo que ir y explorar el asunto por mí misma.",
  ui_story_30960401_123_dialog_content = "En fin, por eso debo encontrar a Gabriela.",
  ui_story_30960401_124_dialog_content = "(Tengo el presentimiento de que el \"omnisciente\" Señor Sombrío está ocultando algo ...)",
  ui_story_30960401_125_dialog_content = "(Y luego está Kleken...)",
  ui_story_30960401_127_dialog_content = "Ella no tiene ningún control sobre su poder. Lo sabes, ¿no?",
  ui_story_30960401_128_dialog_content = "Las dos personalidades volátiles de Sariel dictan que debe mantenerse bajo la supervisión del Señor Sombrío en todo momento, por el bien de la seguridad.",
  ui_story_30960401_130_dialog_content = "O tal vez—¿bajo tu supervisión, PlayerName?",
  ui_story_30960401_131_dialog_content = "Tienes muchas cargas que llevar, PlayerName... y un largo camino por delante.",
  ui_story_30960401_133_dialog_content = "Todo se ha ido...",
  ui_story_30960401_134_dialog_content = "Debido a... demolición incontrolada y \"lesiones no intencionales\".",
  ui_story_30960401_136_dialog_content = "(Eso es lo que ese tipo debe haber estado pensando.)",
  ui_story_30960401_137_dialog_content = "Así que...",
  ui_story_30960401_138_dialog_content = "Me asustaste por un segundo.",
  ui_story_30960401_139_dialog_content = "¿Me puedes ayudar?",
  ui_story_30960401_140_dialog_content = "¡Por supuesto! Eres mi amiga, ¿cierto? Tus problemas son mis problemas.",
  ui_story_30960401_141_dialog_content = "Bueno...",
  ui_story_30960401_142_dialog_content = "Pero.. No tengo tanto dinero, y el dinero que tengo está con Vice. Todos los gastos deben contabilizarse.",
  ui_story_30960401_143_dialog_content = "Comprendo. ¿Dónde está Vice?",
  ui_story_30960401_144_dialog_content = "¡No, no, no! No me refería a eso... Sariel, puedo ayudarte a encontrar a Gabriela.",
  ui_story_30960401_145_dialog_content = "¡Oh! ¡Eso también sería bueno!",
  ui_story_30960401_146_dialog_content = "¿¡No se trataba todo de eso!? ¿¡En serio lo olvidaste!?",
  ui_story_30960401_147_dialog_content = "¿Cuándo? Puedo esperar acá.",
  ui_story_30960401_148_dialog_content = "No importa cuánto tiempo tome, puedo esperar. Ah, no... De hecho, debo regresar a Umbraton a registrarme...",
  ui_story_30960401_149_dialog_content = "Si me registro a las 8:00 de la mañana y luego a las 8:00 de la noche, los números coincidirán perfectamente...",
  ui_story_30960401_150_dialog_content = "Espera... Si están usando un reloj de 24 horas, serán las 8:00 y las 20:00, ¿no es así?",
  ui_story_30960401_151_dialog_content = "¡Espérame! ¡Ya vuelvo!",
  ui_story_30960401_152_dialog_content = "¿S-Sariel?",
  ui_story_30960401_153_dialog_content = "Ya se fue...",
  ui_story_30960401_154_dialog_content = "Amos... Ese era el nombre del abuelo de Sariel.",
  ui_story_30960401_155_dialog_content = "Es difícil imaginar a Gabriela envuelta en un misterio tan siniestro...",
  ui_story_30960401_156_dialog_content = "...",
  ui_story_30960401_157_dialog_content = "Qué pasó exactamente hace diez años...",
  ui_story_30960601_1_dialog_content = "Seguro que hace buen tiempo hoy...",
  ui_story_30960601_2_dialog_content = "<color=#e8d9bb>¡Azote!</color>",
  ui_story_30960601_3_dialog_content = "¡¿D-De dónde vino este pedazo de papel?! Fue directo a mi cara...",
  ui_story_30960601_4_dialog_content = "¿Mmm? Hay algo escrito en él...",
  ui_story_30960601_5_dialog_content = "\"¿Deseas convertirte en una mejor persona? ¿Deseas tener éxito?\"",
  ui_story_30960601_6_dialog_content = "\"¡Entonces ven a Rising Star Agency y regístrate hoy!\"",
  ui_story_30960601_7_dialog_content = "\"¡Con todo tipo de clases y estilos de enseñanza, estamos seguros de satisfacer sus deseos de grandeza!\"",
  ui_story_30960601_8_dialog_content = "\"¡Las clases comienzan en 1998 y los instructores vendrán directamente a su puerta para recibir lecciones!\"",
  ui_story_30960601_9_dialog_content = "\"¡A partir de ahora, tú también puedes cambiar toda tu vida para mejor!\"",
  ui_story_30960601_10_dialog_content = "Eh. Suena algo interesante.",
  ui_story_30960601_11_dialog_content = "¿Disculpe me permite entrar?",
  ui_story_30960601_12_dialog_content = "Claro.",
  ui_story_30960601_13_dialog_content = "hola soy el <color=#FFB400>instructor</color> enviado por la Agencia Rising Star. ¿Cómo lo haces?",
  ui_story_30960601_17_dialog_content = "¡¿S-Sariel?! Por qué eres...?",
  ui_story_30960601_18_dialog_content = "*Tose* Estoy, eh... Trabajando para la agencia Rising Star en este momento.",
  ui_story_30960601_19_dialog_content = "Esto está debajo de la mesa: ¡los beneficios para el trabajo están fuera de este mundo!",
  ui_story_30960601_20_dialog_content = "¡Hasta me dan ropa!",
  ui_story_30960601_21_dialog_content = "Eso es genial, pero... ¿Por qué me cuentas todo esto?",
  ui_story_30960601_22_dialog_content = "Bueno, no se nos permite compartir nada de esta información con otras personas... Pero como somos tan cercanos, pensé en decírtelo.",
  ui_story_30960601_23_dialog_content = "Esta es también la primera vez que doy una clase, así que perdónenme si cometo algunos errores aquí y allá.",
  ui_story_30960601_23X_dialog_content = "Bueno. Entiendo.",
  ui_story_30960601_24_dialog_content = "Ejem... Entonces, sin más preámbulos, comencemos.",
  ui_story_30960601_25_dialog_content = "Las clases que ha seleccionado son: \"Cómo evitar conflictos con los demás\", \"Técnicas secretas: Mandar\" y \"El camino a la riqueza\".",
  ui_story_30960601_26_dialog_content = "Comenzaremos con nuestra primera lección: Cómo evitar conflictos con los demás.",
  ui_story_30960601_27_dialog_content = "Antes de comenzar, me gustaría hacerle algunas preguntas...",
  ui_story_30960601_28_dialog_content = "Si alguien te pidiera que te unieras a su equipo, pero en realidad no quieres unirte, ¿cómo responderías?",
  ui_story_30960601_29_dialog_content = "¿Qué tiene que ver eso con el conflicto?",
  ui_story_30960601_30_dialog_content = "Uh, simplemente estoy tratando de obtener una mejor comprensión de tu personalidad, para que podamos establecer un método positivo de comunicación...",
  ui_story_30960601_31_dialog_content = "En cualquier caso, ¿cuál es su respuesta?",
  ui_story_30960601_32_dialog_content = "R: Agradézcale su gentil invitación y respetuosamente rechace.",
  ui_story_30960601_33_dialog_content = "B: Rechazarla groseramente.",
  ui_story_30960601_34_dialog_content = "declinar respetuosamente",
  ui_story_30960601_35_dialog_content = "Oh, entiendo... Esta pregunta es para ver si puedo tomar la iniciativa para evitar posibles conflictos, ¿no?",
  ui_story_30960601_36_dialog_content = "¡Por supuesto que elegiría declinar cortésmente después de agradecerle!",
  ui_story_30960601_37_dialog_content = "Correcto. Eres bastante perceptivo, ¿no?",
  ui_story_30960601_38_dialog_content = "Rechazarla groseramente",
  ui_story_30960601_39_dialog_content = "Bueno, hubo una persona que me invitó a convertirme en Eclipsite... Eso fue como pedirme que me uniera a su equipo, en cierto modo.",
  ui_story_30960601_40_dialog_content = "Después de eso, la rechacé bastante groseramente... Y luego la derroté en la batalla.",
  ui_story_30960601_41_dialog_content = "Bueno, dada la situación... supongo que hay alguna razón detrás de esa elección de acción, ¿verdad?",
  ui_story_30960601_42_dialog_content = "Ahora bien, siguiente pregunta...",
  ui_story_30960601_43_dialog_content = "Si alguien toma algo que te pertenece y se niega a devolvértelo, ¿qué harías?",
  ui_story_30960601_44_dialog_content = "R: Pídeles educadamente que se expliquen...",
  ui_story_30960601_45_dialog_content = "¡Oh! Hubo alguien que robó un componente que pertenecía a los Caelestites...",
  ui_story_30960601_46_dialog_content = "Aunque no me pertenecía exclusivamente a mí, no podía dejar que cayera en manos de esa persona.",
  ui_story_30960601_47_dialog_content = "Así que elijo B! ¡Derrótala y recupera el componente!",
  ui_story_30960601_48_dialog_content = "Uh... Tu respuesta es un poco fuera de lo común, así que déjame revisar mi folleto muy rápido...",
  ui_story_30960601_49_dialog_content = "Ejem, muy bien. ¿Y crees que tu elección fue la correcta?",
  ui_story_30960601_50_dialog_content = "No... Las cosas nunca son tan simples como todos ustedes piensan.",
  ui_story_30960601_51_dialog_content = "<size=45>¡Nunca son tan simples!</size>",
  ui_story_30960601_52_dialog_content = "¿Por qué tuviste que levantar la voz y decir eso por segunda vez?",
  ui_story_30960601_53_dialog_content = "Porque eso es lo que el folleto nos dice que hagamos.",
  ui_story_30960601_54_dialog_content = "Oh, espera... Nuestros panfletos nos dicen que reproduzcamos anuncios de vez en cuando durante las lecciones. ¡Casi lo olvido!",
  ui_story_30960601_55_dialog_content = "¿Eh? ¿Jugar a qué, ahora...?",
  ui_story_30960601_56_dialog_content = "\"¿Sigues atrapado llevando una vida sin éxito?\"",
  ui_story_30960601_57_dialog_content = "\"¿Sigues devanándote los sesos sobre cómo mejorarte a ti mismo?\"",
  ui_story_30960601_58_dialog_content = "\"¡El éxito no es un método o una condición, sino un estado de ánimo!\"",
  ui_story_30960601_59_dialog_content = "\"¡Deja que nuestros cursos especiales te guíen hacia una vida mejor!\"",
  ui_story_30960601_60_dialog_content = "\"¡Actúe ahora y podrá recibir un 20 % de descuento en todas las clases si sus amigos también se inscriben!\"",
  ui_story_30960601_61_dialog_content = "...",
  ui_story_30960601_62_dialog_content = "¿Te gustaría registrarte?",
  ui_story_30960601_63_dialog_content = "¡Inscríbeme en cinco clases más!",
  ui_story_30960601_64_dialog_content = "Si es por conocimiento, no me importa gastar un poco de dinero extra.",
  ui_story_30960601_65_dialog_content = "¡Estoy seguro de que Vice también lo entenderá!",
  ui_story_30960601_66_dialog_content = "¡Gracias por su patrocinio! ¡No tienes idea de cuánto me ayuda esto!",
  ui_story_30960601_67_dialog_content = "¿Quieres decir?",
  ui_story_30960601_68_dialog_content = "¡Eh, n-nada! De todos modos, debemos continuar con la lección...",
  ui_story_30960601_69_dialog_content = "No hay necesidad",
  ui_story_30960601_70_dialog_content = "Últimamente no tengo mucho dinero...",
  ui_story_30960601_71_dialog_content = "¿Pero no eres tú el famoso Navegante?",
  ui_story_30960601_72_dialog_content = "¡Tienes conexiones y un Coloso para arrancar! Estoy seguro de que un poco de dinero no es un problema...",
  ui_story_30960601_73_dialog_content = "Bueno, mantener el Coloso en el aire y asegurarse de que todos estén cómodos y felices también cuesta dinero...",
  ui_story_30960601_74_dialog_content = "No debería gastar más, así que continuemos con la clase.",
  ui_story_30960601_75_dialog_content = "Bien entonces. No puedo obligarte si no estás dispuesto a hacerlo... Sigamos, entonces...",
  ui_story_30960601_76_dialog_content = "El conflicto se puede dividir en muchos tipos. Permítanme ilustrar esto con un dibujo.",
  ui_story_30960601_77_dialog_content = "Y... Otro dibujo...",
  ui_story_30960601_78_dialog_content = "Y otro... Y otro...",
  ui_story_30960601_79_dialog_content = "Eh... ¿Sariel? ¿Cuántos dibujos más vas a hacer?",
  ui_story_30960601_80_dialog_content = "¡Aférrate! ¡Necesito dibujar uno más para hacerlo simétrico!",
  ui_story_30960601_81_dialog_content = "Oh, me olvidé por completo de que todo se trata de simetría...",
  ui_story_30960601_82_dialog_content = "Ahora que estamos hablando de eso, tus calcetines... Solo el derecho tiene un agujero.",
  ui_story_30960601_83_dialog_content = "¡¿Qué?!",
  ui_story_30960601_84_dialog_content = "Un segundo, déjame hacer un agujero en el izquierdo...",
  ui_story_30960601_85_dialog_content = "Además, se llaman medias, no calcetines.",
  ui_story_30960601_86_dialog_content = "Olvídate de cómo se llaman, el punto es...",
  ui_story_30960601_87_dialog_content = "Nunca pensé que arruinarías tu ropa así solo para hacerla simétrica.",
  ui_story_30960601_88_dialog_content = "¡Pero ya sabes que las cosas asimétricas me hacen sentir muy incómoda!",
  ui_story_30960601_89_dialog_content = "¿Por qué te importa tanto la simetría, de todos modos? Llegar tan lejos es demasiado, ya sabes...",
  ui_story_30960601_90_dialog_content = "¡Porque la simetría implica equilibrio y estabilidad! Además, solemnidad y belleza!",
  ui_story_30960601_91_dialog_content = "Yo lo llamo la estética del sentido de la simetría.",
  ui_story_30960601_92_dialog_content = "¿Lo sabías?",
  ui_story_30960601_93_dialog_content = "Los lados izquierdos de nuestras caras no son cien por ciento simétricos con los lados derechos.",
  ui_story_30960601_94_dialog_content = "Pero cuando nos miramos en el espejo, tendemos a ignorarlo.",
  ui_story_30960601_95_dialog_content = "Esto se debe a que nacemos con un deseo innato de simetría...",
  ui_story_30960601_96_dialog_content = "¿No es solo porque la diferencia es demasiado pequeña para notarlo?",
  ui_story_30960601_97_dialog_content = "¿Eh? ¿Estás cuestionando seriamente toda la investigación que he hecho sobre la estética de la simetría?",
  ui_story_30960601_98_dialog_content = "Uh... Olvida que dije algo. ¿Pero los cuernos de tu cabeza tampoco son simétricos?",
  ui_story_30960601_99_dialog_content = "¡Ay! ¡N-No menciones eso! ¡Ya es bastante difícil tratar de olvidarlo!",
  ui_story_30960601_100_dialog_content = "¡Volvamos a la lección que nos ocupa!",
  ui_story_30960601_101_dialog_content = "Muy bien, entonces... ¿Podrías explicar más sobre los dibujos que hiciste hace un momento?",
  ui_story_30960601_102_dialog_content = "A ver que dice el folleto...",
  ui_story_30960601_103_dialog_content = "No pareces estar muy familiarizado con los materiales de tu curso... ¿Realmente puedes dar clases así?",
  ui_story_30960601_104_dialog_content = "Lo siento, el jefe de la agencia Rising Star me preparó esto en el último minuto, así que también me está costando entenderlo.",
  ui_story_30960601_105_dialog_content = "Me parece poco fiable...",
  ui_story_30960601_107_dialog_content = "Grrr... ¿Por qué ninguna de estas letras está alineada entre sí?",
  ui_story_30960601_108_dialog_content = "¿Ah?",
  ui_story_30960601_109_dialog_content = "En el folleto, ¿ves? ¡Las últimas filas están completamente desalineadas!",
  ui_story_30960601_110_dialog_content = "\"'Cómo evitar conflictos con otros', Subsección 2:\"",
  ui_story_30960601_111_dialog_content = "\"Después de la primera ronda de preguntas, deberíamos haber establecido una forma positiva de comunicación con el cliente\".",
  ui_story_30960601_112_dialog_content = "\"En este punto, ¡esta es nuestra mejor oportunidad para explicar nuestra filosofía de marketing!\"",
  ui_story_30960601_113_dialog_content = "¡Las letras no están perfectamente alineadas y me está volviendo loco!",
  ui_story_30960601_114_dialog_content = "¡Creo que el contenido del folleto es mucho más preocupante que las cartas mismas, Sariel!",
  ui_story_30960601_115_dialog_content = "Soroz me enseñó durante diecisiete años... Y te puedo decir que no es así como se debe dar una clase.",
  ui_story_30960601_116_dialog_content = "Las clases deben ser espacios para compartir y recibir conocimientos.",
  ui_story_30960601_117_dialog_content = "Es cierto, tampoco se parecen en nada a las lecciones que tomé en el pasado... ¿Pero tal vez este es solo el método más nuevo de enseñanza?",
  ui_story_30960601_118_dialog_content = "Incluso nos dieron entrenamiento también...",
  ui_story_30960601_119_dialog_content = "¿En qué te entrenaron?",
  ui_story_30960601_120_dialog_content = "Bueno, nos mostraron cómo presentarnos y nuestros planes de estudio...",
  ui_story_30960601_121_dialog_content = "Y cómo animar a nuestros clientes a seguir inscritos en las clases... Y cómo <color=#FFB400>promover aún más clases para ellos</color>...",
  ui_story_30960601_122_dialog_content = "¡Esto suena demasiado sospechoso!",
  ui_story_30960601_123_dialog_content = "Si tiene alguna pregunta, comentario o inquietud, no dude en completar este formulario.",
  ui_story_30960601_124_dialog_content = "Además, recuerde calificar su experiencia de clase conmigo hoy como ¡muy satisfactoria!",
  ui_story_30960601_125_dialog_content = "¿Pero por qué? no estoy nada satisfecho...",
  ui_story_30960601_126_dialog_content = "Porque mientras hagas eso, podré obtener todos los beneficios de mi trabajo.",
  ui_story_30960601_127_dialog_content = "Si no lo haces, me descontarán la paga.",
  ui_story_30960601_128_dialog_content = "Estoy prácticamente arruinado y necesito estos beneficios para seguir ganándome la vida.",
  ui_story_30960601_129_dialog_content = "Si me quitan la paga...",
  ui_story_30960601_130_dialog_content = "¿Cómo voy a permitirme alimentarme a mí o a mi gato...?",
  ui_story_30960601_131_dialog_content = "D-No te preocupes. ¡Me aseguraré de calificar la lección como altamente satisfactoria!",
  ui_story_30960601_132_dialog_content = "¿Pero no crees que es un poco duro de su parte deducirte el sueldo si no obtienes la mejor calificación posible?",
  ui_story_30960601_133_dialog_content = "Sin mencionar todos esos otros... puntos cuestionables.",
  ui_story_30960601_134_dialog_content = "¡Definitivamente hay algo mal con este lugar de Rising Star Agency!",
  ui_story_30960601_135_dialog_content = "¿Cómo qué?",
  ui_story_30960601_136_dialog_content = "Espera, déjame ir a preguntarle a algunas personas conocedoras del mercado sobre esto...",
  ui_story_30960601_137_dialog_content = "Es una estafa, ¿no?",
  ui_story_30960601_138_dialog_content = "Definitivamente una estafa.",
  ui_story_30960601_139_dialog_content = "Te han estafado para que trabajes para una organización sospechosa.",
  ui_story_30960601_140_dialog_content = "Puedo decir que esto es un <color=#FFB400>esquema de marketing multinivel</color> con solo mirarlo. Esto no es algo que haría un negocio honesto.",
  ui_story_30960601_143_dialog_content = "P-Pero ya firmé un contrato con la Agencia Rising Star y les pagué un depósito...",
  ui_story_30960601_144_dialog_content = "*Suspiro* ¡No busques trabajo en lugares sospechosos como este!",
  ui_story_30960601_145_dialog_content = "Hay todo tipo de negocios en Umbraton. Algunos son legítimos y otros son todo lo contrario.",
  ui_story_30960601_146_dialog_content = "¡Debes mantener los ojos abiertos para encontrar lugares de trabajo creíbles con antecedentes e historia sólidos!",
  ui_story_30960601_147_dialog_content = "Volveré y le pediré al Gremio que investigue esta Agencia Rising Star.",
  ui_story_30960601_148_dialog_content = "Si tiene documentos firmados, le sugiero que me los deje verlos ahora.",
  ui_story_30960601_149_dialog_content = "Estoy seguro de que el papeleo incluye términos y condiciones destinados a aprovecharse de los desprevenidos.",
  ui_story_30960601_150_dialog_content = "Gracias, muchas gracias.",
  ui_story_30960601_151_dialog_content = "Si realmente son una agencia de estafas, entonces el dinero que pagué...",
  ui_story_30960601_152_dialog_content = "¡¿Fue todo un desperdicio, verdad?!",
  ui_story_30960601_153_dialog_content = "1998 Nightium... Todo mi dinero de bolsillo ganado con tanto esfuerzo...",
  ui_story_30960601_154_dialog_content = "Todo lo que quería era aprender un conocimiento nuevo y valioso. Nunca pensé...",
  ui_story_30960601_155_dialog_content = "No te preocupes, PlayerName. Todavía tengo la intención de terminar de dar tus clases.",
  ui_story_30960601_156_dialog_content = "Nos dieron estos folletos, pero también tengo mis propios materiales del curso para usar.",
  ui_story_30960601_157_dialog_content = "Leí muchos libros, solo para estar más preparado para esto. ¡Mira, yo también tengo mis propias notas!",
  ui_story_30960601_158_dialog_content = "Sariel, tú...",
  ui_story_30960601_159_dialog_content = "¡Y mira! ¡Cada fila está perfectamente alineada!",
  ui_story_30960601_160_dialog_content = "¿Es ese realmente el punto...?",
  ui_story_30960601_161_dialog_content = "De todos modos, he terminado de seguir su folleto... Entonces, ¿todavía estás dispuesto a tomar mi clase?",
  ui_story_30960601_162_dialog_content = "¡Por supuesto!",
  ui_story_30960601_163_dialog_content = "Genial, entonces empecemos desde el principio.",
  ui_story_30960601_164_dialog_content = "Ahora, para entender el conflicto, primero debemos entender su definición.",
  ui_story_30960601_165_dialog_content = "\"La definición de conflicto enfatiza principalmente la existencia y conciencia de las diferencias de intereses...\"",
  ui_story_30960601_167_dialog_content = "Todavía tenemos mucho tiempo en esta clase, así que me aseguraré de elaborar todos estos puntos cuidadosamente.",
  ui_story_30960601_168_dialog_content = "¡Estupendo! ¡Cómo se supone que debe ser una clase real!",
  ui_story_30960601_169_dialog_content = "Je, qué estudiante obediente eres, PlayerName...",
  ui_story_30960602_1_dialog_content = "¡Tengo excelentes noticias, PlayerName!",
  ui_story_30960602_2_dialog_content = "¡Debería poder pagarte por comprarme el almuerzo el otro día!",
  ui_story_30960602_3_option_content = "No te preocupes, fue mi invitación...",
  ui_story_30960602_4_dialog_content = "Eso no servirá. El abuelo solía decir que incluso las hermanas deberían devolverse el dinero después de pedirlo prestado.",
  ui_story_30960602_5_dialog_content = "Además, ¡alguien me ofreció un trabajo súper lucrativo!",
  ui_story_30960602_6_option_content = "¿Te ofreció Lady Sheol un nuevo trabajo?",
  ui_story_30960602_7_dialog_content = "Es un trabajo nuevo, pero no es de ella.",
  ui_story_30960602_8_dialog_content = "La ubicación también parece ser realmente de alto nivel.",
  ui_story_30960602_9_dialog_content = "Entonces, ¿en qué consiste exactamente el trabajo?",
  ui_story_30960602_10_dialog_content = "Me dijeron que incluso un torpe como yo debería poder manejarlo.",
  ui_story_30960602_11_dialog_content = "Todo lo que tengo que hacer es sentarme en una mesa y jugar todo el día.",
  ui_story_30960602_12_dialog_content = "¿Jugar?",
  ui_story_30960602_13_dialog_content = "¡Sí! Es uno de esos juegos en los que lanzan una pequeña bola en una rueda giratoria con muchos números en ella.",
  ui_story_30960602_14_dialog_content = "... ¿Te refieres a algo como una ruleta?",
  ui_story_30960602_15_dialog_content = "No estoy seguro, pero aunque suelo estropear las cosas, ¡jugar es algo en lo que siempre he sido bueno!",
  ui_story_30960602_16_dialog_content = "Espera, ¿así que aceptaste hacer esto sin siquiera conocer el juego?",
  ui_story_30960602_17_dialog_content = "¿Estás seguro de que no te están engañando o algo así? Muchos estafadores suelen aparecer a medida que se acerca el año nuevo...",
  ui_story_30960602_18_dialog_content = "¡De ninguna manera! Además, ya me estafaron el mes pasado; ¿cuáles son las probabilidades de que ocurra dos veces en dos meses?",
  ui_story_30960602_19_dialog_content = "Creo que debería ir contigo, solo para estar seguro...",
  ui_story_30960602_20_dialog_content = "Me preocupa que puedas meterte en problemas serios esta vez.",
  ui_story_30960602_21_dialog_content = "¿No crees que me estás subestimando?",
  ui_story_30960602_22_dialog_content = "Aun así, no me importa si vienes. Después de todo, el jefe dice que me pagan por día.",
  ui_story_30960602_23_dialog_content = "Una vez que cobre mis salarios, podré pagarte y invitarte a una buena comida. ¡Incluso tendrá pollo!",
  ui_story_30960602_24_dialog_content = "<color=#e8d9bb>Al día siguiente, después de llegar a la ubicación designada de Sariel.</color>",
  ui_story_30960602_25_dialog_content = "...",
  ui_story_30960602_26_dialog_content = "¡Hola, PlayerName!",
  ui_story_30960602_27_dialog_content = "¿Qué pasa con esas ropas...?",
  ui_story_30960602_28_dialog_content = "El jefe me los dio y dijo que evitarían que resaltara demasiado.",
  ui_story_30960602_29_dialog_content = "Yo-ya veo... Sí tienen cierta vibra subterránea en ellos.",
  ui_story_30960602_30_dialog_content = "(Qué atuendo increíble...)",
  ui_story_30960602_31_dialog_content = "Pero... realmente... no los soporto...",
  ui_story_30960602_32_dialog_content = "<color=#e8d9bb>Sariel sufre de trastorno obsesivo-compulsivo, especialmente cuando se trata de objetos asimétricos.</color>",
  ui_story_30960602_33_dialog_content = "<color=#e8d9bb>Su condición es tan grave que si tiene una rasgadura en una media, rasgará un agujero en la otra solo para que coincidan.</color>",
  ui_story_30960602_34_dialog_content = "<color=#e8d9bb>Tengo que decir que este atuendo que lleva puesto ahora está tocando todos sus puntos débiles—</color>",
  ui_story_30960602_35_dialog_content = "<color=#e8d9bb>Un accesorio para el cabello asimétrico.</color>",
  ui_story_30960602_36_dialog_content = "<color=#e8d9bb>Un vestido asimétrico.</color>",
  ui_story_30960602_37_dialog_content = "<color=#e8d9bb>Y medias asimétricas.</color>",
  ui_story_30960602_38_dialog_content = "Bu ju...",
  ui_story_30960602_39_dialog_content = "(No va a llorar de verdad, ¿verdad...?)",
  ui_story_30960602_40_dialog_content = "Eh, Sariel? ¿Has mencionado esto con ese estafador... digo, tu jefe?",
  ui_story_30960602_41_dialog_content = "Lo hice... pero el jefe dijo...",
  ui_story_30960602_42_dialog_content = "¿De verdad te quejas de la ropa gratis que te di? Qué pretencioso.",
  ui_story_30960602_43_dialog_content = "¿Vivir en Umbraton todos esos años te quitó el sentido común?",
  ui_story_30960602_44_dialog_content = "Mucha gente está rogando por un trabajo genial como este. Si no lo quieres, estoy seguro de que alguien más lo tomará.",
  ui_story_30960602_45_dialog_content = "En serio, ¡mírate! Después de todos estos años, ¿realmente has aumentado tu patrimonio? ¿Puedes decir que has estado trabajando duro en absoluto?",
  ui_story_30960602_46_dialog_content = "¿Cómo esperas ganar dinero cuando estás dispuesto a rendirte por algo tan trivial?",
  ui_story_30960602_47_dialog_content = "... Eso es todo.",
  ui_story_30960602_48_dialog_content = "¡Eso está totalmente fuera de lugar!",
  ui_story_30960602_49_dialog_content = "También dijo que no me pagarán si no uso esta ropa y que tendré que devolverle el dinero si se rompen.",
  ui_story_30960602_50_dialog_content = "Entonces, a pesar de todo, ¿todavía quieres hacer este trabajo?",
  ui_story_30960602_51_dialog_content = "... YO...",
  ui_story_30960602_52_dialog_content = "... Tengo mis razones para ganar dinero, así que quiero intentarlo.",
  ui_story_30960602_53_dialog_content = "Gracias por acompañarme, por cierto. Contigo cerca... creo que puedo manejarlo un poco mejor...",
  ui_story_30960602_54_dialog_content = "Sariel...",
  ui_story_30960602_55_dialog_content = "(Al principio solo quería asegurarme de que no la estafaran, pero ahora me siento obligado a ayudarla a terminar su trabajo.)",
  ui_story_30960602_56_dialog_content = "No te preocupes, te ayudaré en todo lo que pueda.",
  ui_story_30960602_57_dialog_content = "Boo-hoo... ¡Estoy tan agradecido! No puedo imaginar qué me pasaría sin ti aquí.",
  ui_story_30960602_58_dialog_content = "Jaja, no lo menciones. Ya casi es hora de fichar, ¿verdad? Vamos a ponernos en marcha.",
  ui_story_30960602_59_dialog_content = "<color=#e8d9bb>En la casa de juegos subterránea.</color>",
  ui_story_30960602_60_dialog_content = "<color=#e8d9bb>El sonido de ruedas girando y dados rodando se escucha en todo el lugar, mientras la gente mira con atención las cartas que se voltean en sus mesas.</color>",
  ui_story_30960602_61_dialog_content = "<color=#e8d9bb>Las multitudes alrededor de las mesas vitorean y se lamentan mientras continúan los juegos.</color>",
  ui_story_30960602_62_dialog_content = "(No creo que esté hecho para un lugar como este...)",
  ui_story_30960602_63_dialog_content = "(Pero es por Sariel, así que tengo que apretar los dientes y soportarlo!)",
  ui_story_30960602_64_dialog_content = "Entonces, ¿tu jefe también está aquí, Sariel?",
  ui_story_30960602_65_dialog_content = "Sí, lo acabo de ver hace un segundo. Está justo por... ¿Eh? ¿Dónde se fue?",
  ui_story_30960602_66_dialog_content = "Supongo que no importa. Él me dio este pequeño receptor para poner en mi oído, que puedo usar para comunicarme con él cuando lo necesite. ¡Oh, me está llamando ahora!",
  ui_story_30960602_67_dialog_content = "¿La persona junto a mí? ¿Te refieres a PlayerName? Está aquí para ayudarme... quiero decir, solo es un amigo.",
  ui_story_30960602_68_dialog_content = "Vale, primero tengo que cambiar el dinero que me diste por fichas, y luego sentarme en una de esas mesas...",
  ui_story_30960602_69_dialog_content = "Después de eso, solo elijo un número... y entrego mis fichas...",
  ui_story_30960602_70_dialog_content = "¡E-Espera, estás ofreciendo todos tus tokens?!",
  ui_story_30960602_71_dialog_content = "Oh, ¿es eso algo malo?",
  ui_story_30960602_72_dialog_content = "¡No se supone que vayas con todo en tu primer juego!",
  ui_story_30960602_73_dialog_content = "Treinta y siete, negro. Felicitaciones, señorita, has ganado.",
  ui_story_30960602_74_dialog_content = "Pero él dijo que gané! Y mira, me dio un montón de fichas!",
  ui_story_30960602_75_dialog_content = "¿Cómo exactamente gané de todos modos? ¿Fue porque ofrecí la mayor cantidad de fichas?",
  ui_story_30960602_76_dialog_content = "Supongo que es suerte de principiante... De todos modos, no vayas all-in así de nuevo. Comienza con una o dos fichas y sigue desde ahí.",
  ui_story_30960602_77_dialog_content = "Está bien, tú eres el jefe. Después de todo, parece que sabes más de esto que yo.",
  ui_story_30960602_78_dialog_content = "Tampoco lo entiendo muy bien, pero uno de mis amigos me enseñó algunos trucos antes.",
  ui_story_30960602_79_dialog_content = "(Aunque solo aprendí estas cosas para evitar ser engañado, parece que finalmente puedo darles un buen uso...)",
  ui_story_30960602_80_dialog_content = "Entonces, ¿qué significa exactamente \"all-in\"?",
  ui_story_30960602_81_dialog_content = "...",
  ui_story_30960602_82_dialog_content = "Dos, rojo. Felicitaciones, señorita, has ganado.",
  ui_story_30960602_83_dialog_content = "Increíble...",
  ui_story_30960602_84_dialog_content = "¡Veinticinco victorias seguidas! ¡Esta chica debe ser la Dama de la Suerte en persona!",
  ui_story_30960602_85_dialog_content = "¡También necesitamos estar a su nivel!",
  ui_story_30960602_86_dialog_content = "Uh, PlayerName? ¿Por qué todos me están mirando?",
  ui_story_30960602_87_dialog_content = "Este juego no es tan difícil. Siempre que ofrezcas un número par de fichas, siempre ganas.",
  ui_story_30960602_88_dialog_content = "Bajaría mi voz si fuera tú. Nos meteríamos en problemas si esas personas te escuchan después de perder tantas veces.",
  ui_story_30960602_89_dialog_content = "Aunque parece bastante extraño. Ya has ganado veinticinco veces... Y apostando solo a números individuales, nada menos.",
  ui_story_30960602_90_dialog_content = "Incluso con una suerte increíble, esto parece demasiado improbable. ¿Tal vez la casa de juegos te está utilizando como señuelo?",
  ui_story_30960602_91_dialog_content = "¿Qué quieres decir con \"cómplice\"?",
  ui_story_30960602_92_dialog_content = "... No importa. Llevaría demasiado tiempo explicarlo.",
  ui_story_30960602_93_dialog_content = "De todos modos, apenas puedo sostener todas estas fichas... Creo que eso debería ser suficiente por ahora.",
  ui_story_30960602_94_dialog_content = "¿Eh? Es el jefe otra vez...",
  ui_story_30960602_95_dialog_content = "¿Qué es eso? ¿Quieres que siga jugando o si no, no me pagarán? Pero ¿por qué...?",
  ui_story_30960602_96_dialog_content = "¿Tu jefe quiere que sigas adelante?",
  ui_story_30960602_97_dialog_content = "Bueno, no es lo más honesto que hacer, pero si eso es lo que él quiere de ti... Supongo que está bien.",
  ui_story_30960602_98_dialog_content = "Entonces, ¿cuál es el punto de todo esto? Estoy empezando a aburrirme... Y estas ropas me están volviendo loco...",
  ui_story_30960602_99_dialog_content = "Bostezo—<size=45>¡Guau!</size>",
  ui_story_30960602_100_dialog_content = "Sariel choca con su montaña de fichas al estirar la espalda, pero logra evitar que se caiga al girar rápidamente fuera del camino.",
  ui_story_30960602_101_dialog_content = "Lamentablemente, la maniobra incómoda hace que ella patee su silla y choque con la mesa.",
  ui_story_30960602_102_dialog_content = "Se necesita cierta habilidad para caer de una manera tan espectacular.",
  ui_story_30960602_103_dialog_content = "Ay...",
  ui_story_30960602_104_dialog_content = "... ¿Estás bien? ¿Te lastimaste hace un momento?",
  ui_story_30960602_105_dialog_content = "Creo que me desgarré un músculo de la espalda... Me duele bastante...",
  ui_story_30960602_106_dialog_content = "No, espera, siento como si algo me estuviera pinchando desde debajo de mi espalda.",
  ui_story_30960602_107_dialog_content = "¿Podrías ayudarme a sacarlo? No lo puedo alcanzar...",
  ui_story_30960602_108_dialog_content = "... ¿Debajo de tu espalda? Lo intentaré...",
  ui_story_30960602_109_dialog_content = "Ahh...",
  ui_story_30960602_110_dialog_content = "¿Qué es?",
  ui_story_30960602_111_dialog_content = "Nada, simplemente se sintió mucho mejor cuando me frotaste la espalda en ese lugar...",
  ui_story_30960602_112_dialog_content = "Eh, ¿entonces dónde está esta cosa que te está pinchando?",
  ui_story_30960602_113_dialog_content = "... Oh, cierto... Creo que está un poco más bajo.",
  ui_story_30960602_114_dialog_content = "... Uh... No siento nada ahí abajo.",
  ui_story_30960602_115_dialog_content = "No, es un poco más bajo...",
  ui_story_30960602_116_dialog_content = "Más bajo...",
  ui_story_30960602_117_dialog_content = "Ah, ahí está... ¿Eh? ¿Qué es esto?",
  ui_story_30960602_118_dialog_content = "<size=45>¡Eso es mío! ¡Devuélvelo!</size>",
  ui_story_30960602_119_dialog_content = "Un anciano arrebata el objeto antes de que alguien pueda echarle un buen vistazo.",
  ui_story_30960602_120_dialog_content = "Espera... ¿No eres uno de los jugadores en nuestra mesa? Lo siento, pero ¿qué es eso...?",
  ui_story_30960602_121_dialog_content = "<size=45>¡Detén a ese hombre!</size>",
  ui_story_30960602_122_dialog_content = "¡Tiene un dispositivo para hacer trampa en sus manos!",
  ui_story_30960602_123_dialog_content = "¿Qué? ... ¡Oye, está intentando escapar!",
  ui_story_30960602_124_dialog_content = "<size=45>¡Después de él!</size>",
  ui_story_30960602_125_dialog_content = "<size=45>¡Bloquea la salida! ¡No dejes que se escape!</size>",
  ui_story_30960602_126_dialog_content = "<color=#e8d9bb>Gracias a su respuesta extremadamente rápida, los empleados detienen rápidamente al anciano tramposo.</color>",
  ui_story_30960602_127_dialog_content = "<color=#e8d9bb>Poco después, todas las victorias y derrotas en esa mesa fueron consideradas inválidas.</color>",
  ui_story_30960602_128_dialog_content = "<color=#e8d9bb>En otras palabras, el tiempo y esfuerzo que Sariel y yo invertimos aquí fue todo en vano.</color>",
  ui_story_30960602_129_dialog_content = "Debo decir, no esperaba que las cosas terminaran así en absoluto.",
  ui_story_30960602_130_dialog_content = "Ahí va todo mi pago... boo-hoo...",
  ui_story_30960602_131_option_content = "Solo agradece que no te metiste en problemas.",
  ui_story_30960602_132_option_content = "Al menos ayudaste a atrapar a un tramposo.",
  ui_story_30960602_133_dialog_content = "No puedo creer que la persona que te contrató te haya utilizado así para estafar y obtener ganancias después.",
  ui_story_30960602_134_dialog_content = "De todos modos, probablemente no entiendas nada de lo que acabo de decir...",
  ui_story_30960602_135_dialog_content = "¿Por qué me usaría para engañar en lugar de hacerlo él mismo?",
  ui_story_30960602_136_dialog_content = "Creo que él te estaba usando para desviar la atención de sí mismo. Al hacerte parecer la Dama de la Suerte, él seguiría jugando sin levantar demasiadas sospechas.",
  ui_story_30960602_137_dialog_content = "Apuesto a que la ropa que él te dio también tenía la intención de desviar la atención de la gente de él.",
  ui_story_30960602_138_dialog_content = "Ya veo... Pero aún no lo entiendo.",
  ui_story_30960602_139_dialog_content = "Entonces, ¿qué debería hacer con este atuendo?",
  ui_story_30960602_140_dialog_content = "Sin idea. ¿Crees que deberías devolvérselo aunque ya haya sido arrestado?",
  ui_story_30960602_141_dialog_content = "De ninguna manera. Si hago eso, realmente no obtendré nada de este trabajo.",
  ui_story_30960602_142_dialog_content = "Además... Ya es hora de que me entrene para manejar situaciones difíciles...",
  ui_story_30960602_143_dialog_content = "¿Qué quieres decir?",
  ui_story_30960602_144_dialog_content = "Pasé un día entero usando esta ropa horrible, pero cada vez que empezaba a sentirme incómodo... pensaba en ti.",
  ui_story_30960602_145_dialog_content = "¿Tú... pensaste en mí?",
  ui_story_30960602_146_dialog_content = "Sí. Pensé en lo que me dijiste y en cómo estuviste ahí para ayudarme.",
  ui_story_30960602_147_dialog_content = "... Después de eso... Ya no me sentí tan incómodo.",
  ui_story_30960602_148_dialog_content = "...",
  ui_story_30960602_149_dialog_content = "J-Justo como... Cuando me frotabas la espalda. Se sentía igual de cómodo.",
  ui_story_30960602_150_dialog_content = "¡Son dos cosas totalmente diferentes! ¿Y por qué tienes que decirlo así...?",
  ui_story_30960602_151_dialog_content = "De todos modos, quiero entrenarme para tolerar cosas asimétricas usando este atuendo de nuevo... ¿Me ayudarás?",
  ui_story_30960602_152_dialog_content = "(Sariel siempre parece perezoso, pero...)",
  ui_story_30960602_153_dialog_content = "(... Pero incluso ella tiene sus días serios, supongo.)",
  ui_story_30960602_154_dialog_content = "Claro, ¡estaré feliz de ayudar!",
  ui_story_30960602_155_dialog_content = "Usa lo que quieras y te ayudaré a entrenar todo el tiempo que necesites.",
  ui_story_30960602_156_dialog_content = "Jejeje, ¡gracias! Realmente eres la persona más increíble que he conocido en mi vida.",
  ui_story_30960602_157_dialog_content = "Parece que hoy no fue un fracaso total después de todo.",
  ui_story_30960602_158_dialog_content = "... Lo que me recuerda, Lady Sheol dice que comas una cena de pollo después de salir de una casa de juegos.",
  ui_story_30960602_159_dialog_content = "¿Tienes algo de dinero?",
  ui_story_30960602_160_dialog_content = "Yo no...",
  ui_story_30960602_161_dialog_content = "Está bien, hoy invito yo.",
  ui_story_30960602_162_dialog_content = "¡¿En serio?!",
  ui_story_30960602_163_dialog_content = "Realmente eres el mejor, PlayerName!"
}
